// ETL: extraer, transformar en el script y cargar limpio
const filas = await origen.query('SELECT * FROM clientes_legacy');
const clientes = filas
  .filter((f) => f.email)                         // descarta inválidos
  .map((f) => ({
    email: f.email.trim().toLowerCase(),
    nombre: `${f.nombres} ${f.apellidos}`,
  }));
await destino.clientes.bulkWrite(
  clientes.map((c) => ({
    updateOne: { filter: { email: c.email }, update: { $set: c }, upsert: true },
  }))
);

